defmodule Jairojobs.SchemaTest do
  # ADR-0004: every schema gets a UUID v7 primary key, binary_id foreign keys,
  # and microsecond UTC timestamps via `use Jairojobs.Schema`.
  use ExUnit.Case, async: true

  defmodule Sample do
    use Jairojobs.Schema

    schema "samples" do
      field :name, :string
      belongs_to :parent, __MODULE__
      timestamps()
    end
  end

  test "ADR-0004: primary key is an app-generated UUID v7" do
    assert Sample.__schema__(:primary_key) == [:id]
    assert Sample.__schema__(:type, :id) == Ecto.UUID
    # The id is autogenerated by Ecto.UUID with version: 7 (not a DB-side default).
    assert {[:id], {Ecto.UUID, :autogenerate, [[version: 7]]}} in Sample.__schema__(:autogenerate)

    # Generate through the same path and check the version nibble is 7.
    {:ok, <<_::48, version::4, _::76>>} =
      Ecto.UUID.autogenerate(version: 7) |> Ecto.UUID.dump()

    assert version == 7
  end

  test "ADR-0004: foreign keys are binary ids" do
    assert Sample.__schema__(:type, :parent_id) == Ecto.UUID
  end

  test "ADR-0004: timestamps are utc_datetime_usec" do
    assert Sample.__schema__(:type, :inserted_at) == :utc_datetime_usec
    assert Sample.__schema__(:type, :updated_at) == :utc_datetime_usec
  end
end
